import { getNumericStyle } from "../getNumericStyle";
export const getMargins = (element) => {
    const styles = getComputedStyle(element);
    return {
        top: getNumericStyle(styles, "margin-top"),
        bottom: getNumericStyle(styles, "margin-bottom"),
        left: getNumericStyle(styles, "margin-left"),
        right: getNumericStyle(styles, "margin-right")
    };
};
